     $billing=(string)($_POST['default_billing_type']??'MENSAL');if(!in_array($billing,['MENSAL','UNICA','SEMANAL','QUINZENAL','TRIMESTRAL','SEMESTRAL','ANUAL'],true))$billing='MENSAL';$billingMode=contracts_billing_mode_normalize((string)($_POST['billing_mode']??'MANUAL'));$notes=trim((string)($_POST['notes']??''));
