     else{$num=contracts_next_number($pdo,$cid);$st=$pdo->prepare('INSERT INTO contracts(company_id,contract_number,registration_date,status,release_date,block_date,cancellation_date,validity_start,validity_end,contracting_person_id,contracting_person_name,billing_person_id,billing_person_name,chart_account_id,bank_account_id,payment_method_id,due_day,cost_center_id,default_billing_type,billing_mode,notes,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute([$cid,$num,$reg,$status,$release,$block,$cancel,$validityStart,$validityEnd,$contractingId,$cp['name'],$billingId,$bp['name'],$chart,$bank,$paymentMethod,$due,$costCenter,$billing,$billingMode,$notes,$uid,$uid]);$id=(int)$pdo->lastInsertId();}
