     $vs=cvalid_date($_POST['validity_start']??'');$rawVe=cvalid_date($_POST['validity_end']??'');$ind=!empty($_POST['indefinite_term'])?1:0;if($rawVe)$ind=0;$ve=$ind?null:$rawVe;if(!$ind&&!$ve)throw new RuntimeException('Informe a vigência final do item ou marque Vigência indeterminada.');if($vs&&$ve&&$ve<$vs)throw new RuntimeException('A vigência final do item não pode ser anterior à vigência inicial.');$grace=cvalid_date($_POST['grace_date']??'');$nextAdjustment=cvalid_date($_POST['next_adjustment_date']??'');
