<div id="personModal" class="ce-modal-bg"><div class="ce-modal"><div class="ce-modal-head"><strong id="personTitle">Buscar pessoa</strong><span style="flex:1"></span><button type="button" class="ce-btn" data-close="personModal">Fechar</button></div><div class="ce-modal-body"><div class="ce-inline"><input id="personSearch" placeholder="Digite e pressione Enter"><button type="button" class="ce-btn primary" id="personSearchBtn">Pesquisar</button></div><div class="ce-hint">Pesquisa vazia ao abrir. Enter pesquisa; ↑/↓ percorrem; Enter seleciona. F8 abre a busca principal.</div><div id="personResults" class="ce-results"></div></div></div></div>
<div id="productModal" class="ce-modal-bg"><div class="ce-modal"><div class="ce-modal-head"><strong>Buscar produto / serviço</strong><span style="flex:1"></span><button type="button" class="ce-btn" data-close="productModal">Fechar</button></div><div class="ce-modal-body"><div class="ce-inline"><input id="productSearch" placeholder="Digite e pressione Enter"><button type="button" class="ce-btn primary" id="productSearchBtn">Pesquisar</button></div><div class="ce-hint">Pesquisa vazia ao abrir. Enter pesquisa; ↑/↓ percorrem; Enter seleciona.</div><div id="productResults" class="ce-results"></div></div></div></div>
<script>
(()=>{const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));let target=null,rows=[],idx=-1,role='customer';
function open(id,input){document.getElementById(id)?.classList.add('open');if(input){input.value='';setTimeout(()=>input.focus(),30)}rows=[];idx=-1;const list=document.getElementById(id==='personModal'?'personResults':'productResults');if(list)list.innerHTML='';}
function close(id){document.getElementById(id)?.classList.remove('open')};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>close(b.dataset.close));
function draw(listId,data,person){rows=data;idx=data.length?0:-1;document.getElementById(listId).innerHTML=data.map((r,i)=>`<div class="ce-result ${i===0?'sel':''}" data-i="${i}"><strong>${esc(person?r.name:r.nome)}</strong><div class="ce-muted">${esc(person?((window.nexaMaskDoc||String)(r.document||'')||r.phone||''):(r.numero_cadastro||'Sem código')+' · '+('R$ '+Number(r.preco||0).toFixed(2).replace('.',',')))}</div></div>`).join('')||'<div class="ce-result ce-muted">Nenhum registro encontrado.</div>';document.querySelectorAll('#'+listId+' [data-i]').forEach(el=>el.onclick=()=>choose(Number(el.dataset.i),person));}
function mark(listId){document.querySelectorAll('#'+listId+' [data-i]').forEach((e,i)=>e.classList.toggle('sel',i===idx));document.querySelector('#'+listId+' [data-i="'+idx+'"]')?.scrollIntoView({block:'nearest'});}
function choose(i,person){const r=rows[i];if(!r)return;if(person){document.getElementById(target.id).value=r.id;document.getElementById(target.name).value=r.name;close('personModal');}else{document.getElementById('product_id').value=r.id;document.getElementById('product_name').value=r.nome;document.getElementById('itemTablePrice').value=Number(r.preco||0).toFixed(2).replace('.',',');document.getElementById('itemUnitPrice').value=Number(r.preco||0).toFixed(2).replace('.',',');if(document.getElementById('itemCost'))document.getElementById('itemCost').value=Number(r.custo||0).toFixed(2).replace('.',',');close('productModal');}}
async function searchPeople(){const q=document.getElementById('personSearch').value;const j=await fetch('contratos_ajax.php?action=people&role='+encodeURIComponent(role)+'&q='+encodeURIComponent(q)).then(r=>r.json());draw('personResults',j.rows||[],true)}async function searchProducts(){const q=document.getElementById('productSearch').value;const j=await fetch('contratos_ajax.php?action=products&q='+encodeURIComponent(q)).then(r=>r.json());draw('productResults',j.rows||[],false)}
const itemModal=document.getElementById('itemModal');document.getElementById('newItemBtn')?.addEventListener('click',()=>{itemModal?.classList.add('open');setTimeout(()=>document.getElementById('productLookup')?.focus(),30)});const ind=document.getElementById('itemIndefinite'),vend=document.getElementById('itemValidityEnd');function syncValidity(){if(!ind||!vend)return;vend.disabled=ind.checked;if(ind.checked)vend.value='';}ind?.addEventListener('change',syncValidity);vend?.addEventListener('change',()=>{if(vend.value&&ind){ind.checked=false;syncValidity()}});syncValidity();
document.querySelectorAll('.lookup-person').forEach(b=>b.onclick=()=>{target={id:b.dataset.id,name:b.dataset.name};role=b.dataset.role||'customer';document.getElementById('personTitle').textContent=role==='seller'?'Buscar vendedor':'Buscar cliente';open('personModal',document.getElementById('personSearch'))});document.getElementById('productLookup')?.addEventListener('click',()=>open('productModal',document.getElementById('productSearch')));document.getElementById('personSearchBtn').onclick=searchPeople;document.getElementById('productSearchBtn')?.addEventListener('click',searchProducts);
[['personSearch',searchPeople,'personResults',true],['productSearch',searchProducts,'productResults',false]].forEach(([id,fn,list,person])=>{const e=document.getElementById(id);if(!e)return;e.addEventListener('keydown',ev=>{if(ev.key==='ArrowDown'&&rows.length){ev.preventDefault();idx=Math.min(rows.length-1,idx+1);mark(list)}else if(ev.key==='ArrowUp'&&rows.length){ev.preventDefault();idx=Math.max(0,idx-1);mark(list)}else if(ev.key==='Enter'){ev.preventDefault();if(rows.length&&idx>=0&&e.dataset.last===e.value)choose(idx,person);else{e.dataset.last=e.value;fn()}}});e.addEventListener('input',()=>{e.dataset.last='__dirty__';rows=[];idx=-1})});
document.addEventListener('keydown',ev=>{if(ev.key==='F8'){ev.preventDefault();if(itemModal?.classList.contains('open'))document.getElementById('productLookup')?.click();else{const b=document.querySelector('.lookup-person[data-id="contracting_person_id"]');b?.click()}}if(ev.key==='Escape'){close('personModal');close('productModal');if(itemModal?.classList.contains('open'))location.href='contrato_editar.php?id=<?=$id?>&tab=itens'}});
})();
</script><?php admin_footer(); ?>
